package com.englishhero.practice;

import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import tools.jackson.databind.ObjectMapper;
import com.englishhero.identity.*;
import com.englishhero.reading.*;
import com.englishhero.web.BusinessException;
import static com.englishhero.practice.PracticePaperDtos.*;

@Service @Transactional(isolation=Isolation.READ_COMMITTED)
public class PracticePaperAttemptService {
 private final PracticePaperMapper papers;private final PracticePaperContentService content;private final PracticeSetMapper sets;private final PracticeAttemptMapper users;private final IdentityService identities;private final PracticePublicationChecks hashes;private final ObjectMapper json;private final PracticeAudioService audio;private final PracticePaperMistakeLedger mistakeLedger;
 public PracticePaperAttemptService(PracticePaperMapper papers,PracticePaperContentService content,PracticeSetMapper sets,PracticeAttemptMapper users,IdentityService identities,PracticePublicationChecks hashes,ObjectMapper json,PracticeAudioService audio,PracticePaperMistakeLedger mistakeLedger){this.papers=papers;this.content=content;this.sets=sets;this.users=users;this.identities=identities;this.hashes=hashes;this.json=json;this.audio=audio;this.mistakeLedger=mistakeLedger;}
 private PracticePaperMapper.Run owned(SessionPrincipal actor,String id,boolean lock){identities.current(actor);return papers.run(actor.userId(),ArticleRules.id(id,"attemptId"),lock);}
 private void version(PracticePaperMapper.Run r,Integer v){if(v==null||v!=r.lock()||!"IN_PROGRESS".equals(r.status()))throw PracticeAttemptService.conflict();}
 private Attempt dto(PracticePaperMapper.Run r){var v=papers.version(r.version());var cs=papers.components(v.id());var rs=papers.responses(r.id());var map=new HashMap<String,ResponseInput>();rs.forEach(x->map.put(x.slot(),x));var values=cs.stream().map(c->content.component(c,map.get(c.slot()),"COMPLETED".equals(r.status()),r.started(),r.completed())).toList();return new Attempt(""+r.id(),""+r.paper(),""+r.version(),v.metadata().title(),v.metadata().sourceNote(),r.status(),r.lock(),r.slot(),r.question(),rs,values,r.started(),r.completed());}
 public Attempt get(SessionPrincipal actor,String id){return dto(owned(actor,id,false));}
 public Attempt start(SessionPrincipal actor,String id,StartInput input){identities.current(actor);if(input==null)throw BusinessException.invalid("requestId","请提供开始请求");PracticeAttemptService.requestId(input.requestId());long pid=ArticleRules.id(id,"paperId");users.lockUser(actor.userId());String hash=hashes.hash(List.of(id,input));var replay=papers.replay(actor.userId(),"START",input.requestId(),hash);if(replay!=null)return dto(papers.run(actor.userId(),replay,false));var p=papers.paper(pid,true);var active=papers.active(actor.userId(),pid);if(active!=null){papers.remember(actor.userId(),"START",input.requestId(),hash,active.id());return dto(active);}if(!"PUBLISHED".equals(p.status())||p.published()==null)throw new BusinessException(409,"PRACTICE_PAPER_UNAVAILABLE","整卷已下架");if(!Objects.equals(input.paperVersionId(),""+p.published()))throw PracticeAttemptService.conflict();var cs=papers.components(p.published());cs.stream().map(c->content.version(c.setVersionId()).setId()).distinct().sorted().forEach(sid->sets.get(sid,true));cs.forEach(c->content.descriptor(c,true));long aid=papers.insert("INSERT INTO practice_paper_attempt(user_id,paper_id,paper_version_id) VALUES(?,?,?)",actor.userId(),pid,p.published());for(var c:cs){var response=new ResponseInput(c.slot(),"",Map.of());papers.initialize(aid,p.published(),response);}papers.remember(actor.userId(),"START",input.requestId(),hash,aid);return dto(papers.run(actor.userId(),aid,false));}
 public Attempt save(SessionPrincipal actor,String id,DraftInput input){identities.current(actor);if(input==null)throw BusinessException.invalid("responses","请提供作答");users.lockUser(actor.userId());var r=owned(actor,id,true);version(r,input.expectedLockVersion());var values=content.validate(papers.components(r.version()),input.responses(),input.currentSlot(),input.currentQuestionId());papers.responses(r,values,null);papers.advance(r,input.currentSlot(),input.currentQuestionId(),false);return dto(papers.run(actor.userId(),r.id(),false));}
 public Attempt submit(SessionPrincipal actor,String id,SubmitInput input){identities.current(actor);if(input==null||!Boolean.TRUE.equals(input.confirmUnanswered()))throw BusinessException.invalid("confirmUnanswered","请先检查并确认整卷交卷");PracticeAttemptService.requestId(input.requestId());users.lockUser(actor.userId());String hash=hashes.hash(List.of(id,input));Long replay=papers.replay(actor.userId(),"SUBMIT",input.requestId(),hash);if(replay!=null)return dto(papers.run(actor.userId(),replay,false));var r=owned(actor,id,true);version(r,input.expectedLockVersion());var cs=papers.components(r.version());var values=content.validate(cs,input.responses(),input.currentSlot(),input.currentQuestionId());var results=new HashMap<String,Object>();for(int n=0;n<cs.size();n++){var c=cs.get(n);var v=content.version(c.setVersionId());if(PracticeSubjectiveRules.isSubjective(v.readingType()))results.put(c.slot(),Map.of("wordCount",PracticeSubjectiveRules.words(values.get(n).text())));else{var choices=values.get(n).choices();var qs=content.questions(v);var answers=qs.stream().map(q->Map.of("questionId",""+q.id(),"correct",Objects.equals(choices.get(""+q.id()),q.answer()))).toList();results.put(c.slot(),Map.of("answers",answers,"total",qs.size(),"correctCount",answers.stream().filter(a->Boolean.TRUE.equals(a.get("correct"))).count()));}}papers.responses(r,values,results);papers.advance(r,input.currentSlot(),input.currentQuestionId(),true);mistakeLedger.recordPaper(r,values,papers.run(actor.userId(),r.id(),false).completed());papers.remember(actor.userId(),"SUBMIT",input.requestId(),hash,r.id());return dto(papers.run(actor.userId(),r.id(),false));}
 public ReadingDtos.PageDto<History> history(SessionPrincipal actor,PaperQuery q){identities.current(actor);var values=papers.history(actor.userId()).stream().filter(r->{var d=papers.version(r.version()).metadata();return q.exam().equals(d.examCode())&&(q.year()==null||q.year().equals(d.year()))&&(q.month()==null||q.month().equals(d.month()));}).toList();return new ReadingDtos.PageDto<>(values.stream().skip((long)(q.page()-1)*q.pageSize()).limit(q.pageSize()).map(r->new History(""+r.id(),""+r.paper(),papers.version(r.version()).metadata().title(),r.status(),r.started(),r.completed())).toList(),q.page(),q.pageSize(),values.size());}
 public PracticeAudioService.AudioTicketDto audioTicket(SessionPrincipal actor,String id){var r=owned(actor,id,false);var c=papers.components(r.version()).stream().filter(v->v.slot().equals("LISTENING")).findFirst().orElseThrow(PracticeAdminService::missing);var v=content.version(c.setVersionId());var listening=json.readValue(sets.listening(v.id()),PracticeDtos.ListeningData.class);return audio.authorizedTicket(ArticleRules.id(listening.audioAssetId(),"audioAssetId"));}
}

